    assert_eq!(events[events.len()-2].kind, "error");
    let deadline = Instant::now() + Duration::from_secs(3);
    while b.status().restarts == 0 || !b.status().healthy {
        assert!(Instant::now() < deadline); std::thread::sleep(Duration::from_millis(10));
    }
